styles:
.row { display: flex; flex-wrap: wrap; gap: 1rem; align-items: center; }
    .event-log {
      margin-top: 12px;
      padding: 12px;
      border: 1px solid var(--is-border);
      border-radius: 8px;
      background: var(--is-bg-soft);
      font-family: var(--is-mono);
      font-size: 0.8rem;
      min-height: 2em;
      color: var(--is-text);
    }
    .event-log .hint { opacity: 0.6; }

    /* --- Trigger tipo "logo" — el consumer pone SU HTML --- */
    .logo-trigger {
      display: inline-flex;
      align-items: baseline;
      gap: 0;
      padding: 0.45em 0.85em;
      background: var(--is-logo-bg, #fff);
      color: var(--is-logo-fg, #111);
      border-radius: 0.45em;
      font: inherit;
      font-weight: 800;
      letter-spacing: -0.045em;
      text-transform: lowercase;
      transition: filter 120ms ease, transform 120ms ease;
    }
    .logo-trigger:hover { filter: brightness(1.05); }
    .logo-trigger:active { transform: translateY(1px); }
    .logo-trigger__lead { color: var(--is-text, #111); }
    .logo-trigger__accent { color: var(--is-accent, dodgerblue); }
    .logo-trigger__caret {
      margin-left: 0.5em;
      font-size: 0.95em;
      opacity: 0.7;
      color: var(--is-text, #111);
    }

    /* --- Items del dropdown — el consumidor define el HTML
       y el CSS local para esos items. Estos estilos no pueden
       vivir en palette-selector.css porque chaque consumer tiene su
       propio look. --- */
    .my-option {
      display: flex;
      align-items: center;
      gap: 0.6em;
      padding: 0.5em 0.7em;
      border-radius: 0.4em;
      cursor: pointer;
      font-size: 0.875em;
      font-weight: 800;
      letter-spacing: -0.02em;
      text-transform: lowercase;
      transition: background 100ms ease;
    }
    .my-option:hover { background: var(--is-control-bg-hover, #e9ecef); }
    .my-option[aria-selected="true"] { background: color-mix(in srgb, var(--is-accent) 14%, transparent); }
    .my-option__swatch {
      width: 0.85em;
      height: 0.85em;
      border-radius: 999px;
      border: 1px solid color-mix(in srgb, var(--is-text) 18%, transparent);
    }
    .my-option__lead { color: var(--is-text, #111); font-weight: 800; }
    .my-option__accent { font-weight: 800; } /* color puesto por el componente */
    .my-option__check {
      margin-left: auto;
      width: 1em;
      height: 1em;
      color: var(--is-accent);
    }

    .token-option {
      display: flex;
      align-items: center;
      gap: 0.6em;
      padding: 0.45em 0.65em;
      border-radius: 0.4em;
      cursor: pointer;
      font-size: 0.875em;
      transition: background 100ms ease;
    }
    .token-option:hover { background: var(--is-control-bg-hover, #e9ecef); }
    .token-option[aria-selected="true"] { background: color-mix(in srgb, var(--is-accent) 14%, transparent); }
    .token-option__name { font-weight: 600; }
    .token-option__hash {
      font-family: var(--is-mono, monospace);
      font-size: 0.75em;
      opacity: 0.55;
      margin-left: auto;
    }
